Ball-block collision: for each block, find closest point; if dist < r, determine overlap on each axis and reflect.

Standard approach:
```js
function ballBlockCollide(b, blk){
  const cx = Math.max(blk.x, Math.min(b.x, blk.x+blk.w));
  const cy = Math.max(blk.y, Math.min(b.y, blk.y+blk.h));
  const dx = b.x-cx, dy = b.y-cy;
  if (dx*dx+dy*dy > b.r*b.r) return false;
  // resolve: which side
  const overlapX = (blk.w/2 + b.r) - Math.abs(b.x - (blk.x+blk.w/2));
  const overlapY = (blk.h/2 + b.r) - Math.abs(b.y - (blk.y+blk.h/2));
  if (overlapX < overlapY) { b.vx = -b.vx; b.x += (b.x < blk.x+blk.w/2 ? -overlapX : overlapX); }
  else { b.vy = -b.vy; b.y += (b.y < blk.y+blk.h/2 ? -overlapY : overlapY); }
  return true;
}
```

